async function roster(id){if(!id||!allowed())return;const e=epoch,g=snap().generation,r=++rosterQuery,node=$('academic-roster');node.hidden=false;node.textContent='Consultando alumnos y pagos…';try{const d=await rpc('group_detail',{group_id:id});if(!live(e,g)||r!==rosterQuery||draft?.groupId!==id)return;node.innerHTML=(d.students||[]).map(p=>'<button type="button" class="edu-person-row" data-roster-person="'+esc(p.person_id)+'"><span><strong>'+esc(p.name)+'</strong><small>'+esc(p.email||'Sin correo')+' · '+esc(U.states[p.state]||p.state)+'</small></span><span>Total '+U.money(p.total_cents)+' · Recibido '+U.money(p.paid_cents)+' · Falta '+U.money(Number(p.total_cents)-Number(p.paid_cents))+'</span></button>').join('')||'<p>Este grupo todavía no tiene alumnos matriculados.</p>';}catch{if(live(e,g)&&r===rosterQuery)node.textContent='No se confirmó la lista. Vuelve a consultar; los alumnos registrados se conservan.';}}
